class Solution {
public:
    long long maximumImportance(int n, vector<vector<int>>& roads) {
        vector<int> degree(n, 0);
        for (const auto& road : roads) {
            degree[road[0]]++;
            degree[road[1]]++;
        }

        vector<int> degCount(n, 0);
        for (int i = 0; i < n; i++) {
            degCount[degree[i]]++;
        }

        long long result = 0;
        long long value = n;
        for (int d = n - 1; d >= 0; d--) {
            while (degCount[d] > 0) {
                result += (long long)d * value;
                value--;
                degCount[d]--;
            }
        }

        return result;
    }
};
